class Solution {
public:
    std::vector<std::vector<int>> onesMinusZeros(std::vector<std::vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        std::vector<int> ones_row(m, 0), ones_col(n, 0);
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                if (grid[r][c] == 1) {
                    ones_row[r]++;
                    ones_col[c]++;
                }
            }
        }
        std::vector<std::vector<int>> diff(m, std::vector<int>(n, 0));
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                diff[r][c] = 2 * ones_row[r] + 2 * ones_col[c] - m - n;
            }
        }
        return diff;
    }
};

class Solution {
    public int[][] onesMinusZeros(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int[] onesRow = new int[m];
        int[] onesCol = new int[n];
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 1) {
                    onesRow[r]++;
                    onesCol[c]++;
                }
            }
        }
        int[][] diff = new int[m][n];
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                diff[r][c] = 2 * onesRow[r] + 2 * onesCol[c] - m - n;
            }
        }
        return diff;
    }
}

